Algoritma Python:
import pandas as pd, numpy as np
def correlation_feature_selector(df, target_col, threshold=0.85):
    # 1. Hitung korelasi fitur thd target
    features = [c for c in df.columns if c != target_col]
    target_corr = df[features].apply(lambda x: abs(x.corr(df[target_col])))
    # 2. Matriks korelasi antar fitur
    corr_matrix = df[features].corr().abs()
    upper_tri = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
    to_drop = set()
    for col in upper_tri.columns:
        high_corr_cols = upper_tri.index[upper_tri[col] > threshold].tolist()
        for h_col in high_corr_cols:
            # Bandingkan korelasi thd target, buang yang lebih rendah
            if target_corr[h_col] >= target_corr[col]:
                to_drop.add(col)
            else:
                to_drop.add(h_col)
    selected_features = [f for f in features if f not in to_drop]
    return selected_features, list(to_drop)

